(()=>{const $=id=>document.getElementById(id),n=id=>parseFloat($(id).value),inch=v=>$('unit').value==='cm'?v/2.54:v;function go(){const sex=$('sex').value,h=inch(n('height')),neck=inch(n('neck')),waist=inch(n('waist')),hip=inch(n('hip'));$('hipWrap').style.display=sex==='f'?'flex':'none';if(![h,neck,waist].every(Number.isFinite)||h<=0||neck<=0||waist<=0||(sex==='f'&&(!Number.isFinite(hip)||hip<=0))){$('note').textContent='Enter positive measurements.';$('note').className='helper danger';return;}const cv=sex==='m'?waist-neck:waist+hip-neck;if(cv<=0){$('note').textContent='The circumference combination must be greater than zero.';$('note').className='helper danger';return;}const bf=sex==='m'?86.010*Math.log10(cv)-70.041*Math.log10(h)+36.76:163.205*Math.log10(cv)-97.684*Math.log10(h)-78.387;$('bf').textContent=bf.toFixed(1)+'%';$('cv').textContent=cv.toFixed(2)+' in';$('method').textContent=sex==='m'?'Waist − neck':'Waist + hip − neck';$('note').textContent='This is an estimate from circumference equations, not a direct measurement of body composition. Tape placement, rounding and body shape can materially change the result.';$('note').className='helper';}
